from pathlib import Path
import nbformat as N
nb=N.v4.new_notebook(metadata={"kernelspec":{"display_name":"Python 3","language":"python","name":"python3"}})
C=[]
def m(s):C.append(N.v4.new_markdown_cell(s))
def c(s):C.append(N.v4.new_code_cell(s))
m("# Credit Card Fraud Detection — Deep Exploratory Data Analysis\n\n**Machine Learning project | EDA only: no models fitted**\n\n**Dataset:** ULB / Worldline credit-card transactions, September 2013. https://www.kaggle.com/datasets/mlg-ulb/creditcardfraud ; preserved at https://zenodo.org/records/7395559\n\n**Scope:** Inspect all observations; review schema, missingness, duplicates and anomalies; explain display-only transformations; quantify severe class imbalance, amount patterns, relative-time behavior, and anonymous PCA associations. Nine figures in total. The data contain no date, location, customer or merchant identifiers.")
m("## Dataset acquisition, reproducibility and data dictionary\n\nThe original dataset is 150.8 MB. Place creditcard.csv beside this notebook, or download from Zenodo. A shortened sample is not accepted. There are 31 columns: Time (seconds elapsed since the first observation, not local clock time), Amount (currency unspecified), anonymized principal components V1–V28, and Class (0 nonfraud, 1 fraud). Original features of V1–V28 are not known.\n\nThe original data are unchanged. No training, fitted preprocessing or class resampling occurs.")
c("from pathlib import Path\nimport urllib.request, numpy as np, pandas as pd, matplotlib.pyplot as plt, seaborn as sns\nfrom IPython.display import display\nfrom scipy.stats import norm\nsns.set_theme(style='whitegrid',palette='Set2')\nplt.rcParams.update({'figure.figsize':(11,5),'figure.dpi':110,'axes.spines.top':False,'axes.spines.right':False})\ncolor={0:'#277da1',1:'#e76f51'}\np=Path('creditcard.csv')\nif not p.exists():\n for u in ['https://huggingface.co/datasets/David-Egea/Creditcard-fraud-detection/resolve/main/creditcard.csv?download=true','https://huggingface.co/datasets/JEFFREY-VERDIERE/Creditcard/resolve/main/creditcard.csv?download=true','https://zenodo.org/records/7395559/files/creditcard.csv?download=1','https://zenodo.org/api/records/7395559/files/creditcard.csv/content']:\n  try:\n   req=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0'})\n   with urllib.request.urlopen(req,timeout=180) as f, open('creditcard.tmp','wb') as o:\n    while True:\n     b=f.read(1024*1024)\n     if not b:break\n     o.write(b)\n   Path('creditcard.tmp').replace(p)\n   break\n  except Exception as e:\n   print('Download source failed:',str(e)[:140]);Path('creditcard.tmp').unlink(missing_ok=True)\nif not p.exists():raise FileNotFoundError('Download the original creditcard.csv dataset manually from Kaggle.')\ndf=pd.read_csv(p)\nassert df.shape==(284807,31),'Must use the COMPLETE original dataset'\nassert set(df.columns)==set(['Time','Amount','Class']+[f'V{i}' for i in range(1,29)])\nassert set(df.Class.unique())=={0,1}\nprint('FULL dataset loaded:',df.shape)\ndisplay(df.head())")
m("## 1. Data-quality audit and transformation policy\n\nAudit missing cells, types, infinite values, negative amounts, constants, exact duplicates and amount zeros. Exact matching rows are reported, not automatically removed: without a transaction ID one cannot establish that two identical records refer to the same underlying event. Imputation is only appropriate if null values are found; original data have no nulls. The transformed logarithm of amount and elapsed-hour grouping are exclusively for descriptive EDA, without overwriting source columns.")
c("profile=pd.DataFrame({'dtype':df.dtypes.astype(str),'missing':df.isna().sum(),'missing_pct':df.isna().mean()*100,'unique':df.nunique()})\ndisplay(profile)\nprint('Exact duplicate rows retained:',df.duplicated().sum(),'| Zero amounts:',(df.Amount==0).sum())\nprint('Infinity entries:',np.isinf(df.to_numpy()).sum(),'| Negative amounts:',(df.Amount<0).sum())\nassert df.isna().sum().sum()==0 and not np.isinf(df.to_numpy()).any() and (df.Amount>=0).all()\ndisplay(df[['Time','Amount','V1','V2','Class']].describe(percentiles=[.01,.05,.25,.5,.75,.95,.99]).T.round(3))\neda=df.copy();eda['elapsed_hour']=(df.Time//3600).astype(int);eda['log_amount']=np.log1p(df.Amount)\ncounts=df.Class.value_counts().sort_index();rate=counts[1]/len(df)\nprint('Fraud:',counts[1],'of',len(df),'| rate:',f'{rate:.4%}','| elapsed hours:',round(df.Time.max()/3600,2))")
m("## 2. Figure 1 — Class imbalance\n\nThe logarithmic side view reveals the rare fraud group. The absolute count must accompany any rate. High predictive accuracy would be misleading on this imbalanced dataset, but no predictive algorithm is fit in this notebook.")
c("fig,ax=plt.subplots(1,2,figsize=(12,4))\nfor a in ax:a.bar(['Nonfraud','Fraud'],counts.values,color=[color[0],color[1]]);a.set_ylabel('Transactions')\nax[0].set_title('1A. Absolute class frequencies');ax[1].set_yscale('log');ax[1].set_title('1B. Log-scale class frequencies')\nplt.tight_layout();plt.show()")
m("## 3. Figures 2–3 — Transaction amount\n\nAmount is often long-tailed; median and high percentiles are more informative than the mean alone. Plot the class-conditional density on a log(1+Amount) display scale, typical values with outlier markers suppressed only visually, and upper percentiles on a log axis. Neither nulls nor outliers are discarded.")
c("display(df.groupby('Class').Amount.describe(percentiles=[.1,.25,.5,.75,.9,.95,.99]).T.round(3))\nfig,ax=plt.subplots(1,2,figsize=(12,4))\nfor cl,label in [(0,'Nonfraud'),(1,'Fraud')]:ax[0].hist(eda.loc[eda.Class==cl,'log_amount'],bins=np.linspace(0,10,65),density=True,histtype='step',lw=2,color=color[cl],label=label)\nax[0].legend();ax[0].set(title='2A. Amount density (per class)',xlabel='log(1+Amount)',ylabel='Density')\nsns.boxplot(data=eda,x='Class',y='Amount',showfliers=False,ax=ax[1]);ax[1].set_title('2B. Typical amount values');plt.tight_layout();plt.show()\nfig,ax=plt.subplots(figsize=(10,4));qs=[.5,.75,.9,.95,.99,.999]\nfor cl,label in [(0,'Nonfraud'),(1,'Fraud')]:ax.plot([100*q for q in qs],[df.loc[df.Class==cl,'Amount'].quantile(q) for q in qs],marker='o',color=color[cl],label=label)\nax.set_yscale('log');ax.set(xlabel='Percentile',ylabel='Amount (log scale)',title='3. Upper transaction-amount tails');ax.legend();plt.tight_layout();plt.show()")
m("## 4. Figure 4 — Relative-time activity\n\nTime is seconds since the first recorded transaction. The elapsed-hour axis must NOT be interpreted as local hour of day. Counts reflect volume, not individual fraud probabilities.")
c("hour=eda.groupby(['elapsed_hour','Class']).size().unstack(fill_value=0).reindex(columns=[0,1],fill_value=0);hour['total']=hour[0]+hour[1];hour['rate']=hour[1]/hour.total\nfig,ax=plt.subplots(2,1,figsize=(12,7),sharex=True)\nax[0].plot(hour.index,hour.total,color=color[0]);ax[0].set(title='4A. Total activity by elapsed hour',ylabel='Count')\nax[1].bar(hour.index,hour[1],color=color[1]);ax[1].set(title='4B. Fraud counts by elapsed hour',xlabel='Elapsed hour',ylabel='Count')\nplt.tight_layout();plt.show()")
m("## 5. Figure 5 — Fraud rates by elapsed hour, with uncertainty\n\nWilson 95% binomial score intervals illustrate how much a measured hourly fraction can vary with the denominator. No time-of-day causal inference is claimed, and these intervals are not classifier confidence estimates.")
c("z=norm.ppf(.975);nn=hour.total.to_numpy(dtype=float);q=hour.rate.to_numpy();den=1+z*z/nn;mid=(q+z*z/(2*nn))/den;err=z/den*np.sqrt(q*(1-q)/nn+z*z/(4*nn*nn))\nfig,ax=plt.subplots();ax.plot(hour.index,100*q,color=color[1],marker='o',markersize=3,label='Observed fraud %');ax.fill_between(hour.index,100*(mid-err),100*(mid+err),color=color[1],alpha=.2,label='95% Wilson interval')\nax.axhline(100*rate,ls='--',color=color[0],label='Overall baseline');ax.set(title='5. Fraud percentage with uncertainty',xlabel='Elapsed hour, not clock hour',ylabel='Fraud share (%)');ax.legend();plt.tight_layout();plt.show()")
m("## 6. Figure 6 — Anonymized PCA component distributions\n\nCompute a descriptive standardized difference in group means for V1–V28. This is a summary statistic, not feature selection or model training. Display six high-contrast dimensions with no speculative domain labels.")
c("V=[f'V{i}' for i in range(1,29)];g=df.groupby('Class')[V];means=g.mean();std=g.std();contrast=((means.loc[1]-means.loc[0])/np.sqrt((std.loc[0]**2+std.loc[1]**2)/2)).sort_values(key=np.abs,ascending=False)\ndisplay(contrast.head(12).round(3).to_frame('Standardized difference'))\nfig,axes=plt.subplots(2,3,figsize=(13,7))\nfor a,v in zip(axes.flat,contrast.index[:6]):\n lo,hi=df[v].quantile([.005,.995]);bins=np.linspace(lo,hi,51)\n for cl,label in [(0,'Nonfraud'),(1,'Fraud')]:a.hist(df.loc[df.Class==cl,v],bins=bins,density=True,histtype='step',lw=2,color=color[cl],label=label)\n a.set_title(v)\naxes[0,0].legend();fig.suptitle('6. PCA component distributions across class');plt.tight_layout();plt.show()")
m("## 7. Figure 7 — Numeric correlation\n\nPearson correlation is descriptive, not causal and not an estimate of classifier performance. The anonymized dimensions were created by PCA and cannot be assigned business meanings.")
c("corr=df[V+['Time','Amount','Class']].corr();top=corr.Class.drop('Class').abs().nlargest(12).index.tolist()\ndisplay(corr.Class.loc[top].round(4).to_frame('Pearson r'))\nfig,ax=plt.subplots(figsize=(10,8));sns.heatmap(corr.loc[top+['Class'],top+['Class']],cmap='RdBu_r',center=0,vmin=-1,vmax=1,square=True,ax=ax);ax.set_title('7. Correlation matrix');plt.tight_layout();plt.show()")
m("## 8. Figure 8 — Amount-rank deciles\n\nDivide the full dataset into approximately equal-size rank deciles to avoid broken quantile boundaries at tied amounts. Each fraud percentage uses the original full-bin transaction denominator, not an undersampled subset.")
c("eda['amount_decile']=np.minimum(np.ceil(df.Amount.rank(method='first',pct=True)*10).astype(int),10)\ndec=eda.groupby('amount_decile').agg(n=('Class','size'),fraud=('Class','sum'),median_amount=('Amount','median'));dec['fraud_pct']=100*dec.fraud/dec.n;display(dec.round(3))\nfig,ax=plt.subplots(figsize=(10,4));ax.bar(dec.index.astype(str),dec.fraud_pct,color=sns.color_palette('YlOrRd',10));ax.axhline(100*rate,ls='--',color=color[0],label='Overall rate');ax.set(title='8. Fraud share by amount rank decile',xlabel='Amount rank decile',ylabel='Fraud (%)');ax.legend();plt.tight_layout();plt.show()")
m("## 9. Figure 9 — V1/V2 descriptive scatter\n\nThese are two pre-existing components, not a newly fitted projection. Plot all fraud records and 8,000 randomly sampled nonfraud observations for illustrative readability only. Rates and statistics above always use all 284,807 transactions.")
c("legit=df[df.Class==0].sample(n=8000,random_state=42);fraud=df[df.Class==1];fig,ax=plt.subplots(figsize=(10,5));ax.scatter(legit.V1,legit.V2,s=6,alpha=.15,color=color[0],label='Nonfraud display sample');ax.scatter(fraud.V1,fraud.V2,s=18,alpha=.65,color=color[1],label='All fraud')\nax.set(xlabel='V1',ylabel='V2',title='9. Existing V1/V2 PCA coordinates');ax.legend();plt.tight_layout();plt.show()")
m("## 10. Integrity checks, interpretation and limitations\n\nNo imputation is needed when the original source has no missing data. Exact matching rows are retained because there are no unique transaction IDs. Zeros and extreme amounts are preserved because automatic outlier removal could obscure fraud. This dataset dates to September 2013, covers only two days, contains 492 labeled fraud events, and does not provide customer identity, merchant, location, original V1–V28 meaning or verifiable label provenance. Correlation and visualization are not causation or production validation. Future phases may consider class-weighted models and precision/recall, but absolutely none are implemented here.\n\n**References:** ULB / Worldline dataset, https://www.kaggle.com/datasets/mlg-ulb/creditcardfraud ; archival copy, https://zenodo.org/records/7395559 ; Wilson (1927), DOI 10.1080/01621459.1927.10502953.")
c("assert counts.sum()==284807 and hour[1].sum()==counts[1] and dec.fraud.sum()==counts[1] and dec.n.sum()==284807\nresult=pd.Series({'Rows':len(df),'Columns':df.shape[1],'Fraud cases':counts[1],'Fraud percentage':round(rate*100,5),'Missing cells':df.isna().sum().sum(),'Duplicate matching rows (retained)':df.duplicated().sum(),'Zero amount records':(df.Amount==0).sum(),'Maximum amount':df.Amount.max(),'Elapsed duration (hours)':round(df.Time.max()/3600,2)})\ndisplay(result.to_frame('Measured value'));print('VALIDATED: full dataset, EDA only, nine figures.')")
nb.cells=C
N.write(nb,'Credit_Card_Fraud_EDA.ipynb')
print('Created',len(C),'cells')
